settings.css:
   #snooze-linktree {
    --c-coral: #F43357;
    --c-coral-hover: #D62646;
    --c-navy: #1F293B;
    --c-cream: #FAF7F4;
    --c-beige: #F2EDEA;
    --c-white: #FFFFFF;
    --c-sage: #7C8A98;
    --c-text: #161E2A;
    --c-muted: #64748B;

    --font-body: 'Poppins', sans-serif;
    --font-head: 'Playfair Display', serif;

    --radius: 20px;
    --radius-lg: 26px;
    --shadow-card: 0 10px 30px rgba(31, 41, 59, 0.1);
    --shadow-soft: 0 6px 16px rgba(31, 41, 59, 0.08);
    --shadow-hero: 0 20px 48px rgba(244, 51, 87, 0.16);
    --ring: 0 0 0 4px rgba(244, 51, 87, 0.18);

    font-family: var(--font-body);
    color: var(--c-text);
    line-height: 1.6;
    position: relative;
    width: 100%;
    min-height: 100vh;
    background: var(--c-cream);
    overflow: hidden;
    isolation: isolate;
  }

  #snooze-linktree *,
  #snooze-linktree *::before,
  #snooze-linktree *::after {
    box-sizing: border-box;
  }

  #snooze-linktree a {
    color: inherit;
    text-decoration: none;
  }

#snooze-linktree .lt-background {
  position: absolute;
  inset: 0;
  background: var(--c-cream);
  z-index: 0;
}

  #snooze-linktree .lt-shell {
    position: relative;
    z-index: 1;
    max-width: 480px;
    margin: 0 auto;
    padding: 40px 22px 56px;
  }

  /* Header: brand mark only. Kept small and quiet so the hero, not the
     header, is the first thing a visitor's eye lands on. */
  #snooze-linktree .lt-header {
    display: flex;
    justify-content: center;
  }

  #snooze-linktree .lt-brand {
    display: flex;
    flex-direction: column;
    align-items: center;
    gap: 10px;
    text-align: center;
  }

  #snooze-linktree .lt-logo {
    width: 48px;
    height: 48px;
    color: var(--c-coral);
    display: grid;
    place-items: center;
  }

  #snooze-linktree .lt-logo svg {
    width: 100%;
    height: 100%;
  }

  #snooze-linktree .lt-kicker {
    text-transform: uppercase;
    letter-spacing: 0.14em;
    font-size: 0.68rem;
    font-weight: 600;
    color: var(--c-muted);
    margin: 0;
  }

  /* Hero: the unmistakable focal point. Its own panel, distinct from the
     link list below, so it reads as one decision rather than one of many
     equal-weight options. */
  #snooze-linktree .lt-hero {
    margin-top: 28px;
    padding: 32px 24px;
    border-radius: var(--radius-lg);
    background: var(--c-white);
    box-shadow: var(--shadow-hero);
    text-align: center;
    display: grid;
    gap: 18px;
  }

  #snooze-linktree .lt-hero-eyebrow {
    margin: 0;
    font-family: var(--font-head);
    font-size: clamp(1.3rem, 4.6vw, 1.7rem);
    line-height: 1.35;
    color: var(--c-navy);
    text-wrap: balance;
  }

  #snooze-linktree .lt-primary {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    padding: 17px 24px;
    background: var(--c-coral-hover); /* T1 a11y: white-on-coral ~3.4:1 -> Coral Deep ~4.97:1 */
    color: #fff;
    font-weight: 600;
    font-size: 1.02rem;
    border-radius: 999px;
    box-shadow: 0 14px 28px rgba(244, 51, 87, 0.28);
    min-height: 56px;
    transition: transform 0.25s ease, box-shadow 0.25s ease, background 0.25s ease;
  }

  #snooze-linktree .lt-primary:hover {
    background: var(--c-coral-hover);
    transform: translateY(-2px);
    box-shadow: 0 20px 40px rgba(244, 51, 87, 0.32);
  }

  #snooze-linktree .lt-primary.is-pressed {
    transform: translateY(0) scale(0.98);
  }

  #snooze-linktree .lt-primary:focus-visible {
    outline: none;
    box-shadow: var(--ring), 0 16px 30px rgba(244, 51, 87, 0.28);
  }

  #snooze-linktree .lt-links {
    margin-top: 28px;
    display: grid;
    gap: 12px;
  }

/* Entrance is a pure-CSS fade-up (animation-fill-mode: backwards), never
   gated on JS or on scrolling an element into view. A JS/IntersectionObserver
   -gated reveal (the original page's approach) leaves anything below the
   fold permanently invisible if the observer never fires: slow JS, JS
   disabled, or a headless render. Cards are visible by default; the
   animation only enhances that already-visible state. */
@keyframes lt-fade-up {
  from {
    opacity: 0;
    transform: translateY(10px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

#snooze-linktree .lt-card {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 18px;
    padding: 16px 16px;
    border-radius: var(--radius);
    background: rgba(255, 255, 255, 0.95);
    box-shadow: var(--shadow-card);
    animation: lt-fade-up 0.5s ease backwards;
    transition: transform 0.25s ease, box-shadow 0.25s ease, border 0.25s ease, background 0.25s ease;
  border: 1px solid transparent;
}

  #snooze-linktree .lt-card:nth-of-type(1) { animation-delay: 0.05s; }
  #snooze-linktree .lt-card:nth-of-type(2) { animation-delay: 0.13s; }
  #snooze-linktree .lt-card:nth-of-type(3) { animation-delay: 0.21s; }

  #snooze-linktree .lt-card:hover {
    transform: translateY(-1px);
    box-shadow: 0 16px 36px rgba(31, 41, 59, 0.14);
    border-color: rgba(244, 51, 87, 0.14);
  }

  #snooze-linktree .lt-card:focus-visible {
    outline: none;
    box-shadow: var(--ring), var(--shadow-card);
  }

  #snooze-linktree .lt-card-title {
    display: block;
    font-weight: 600;
    font-size: 1rem;
    color: var(--c-navy);
  }

  #snooze-linktree .lt-card-desc {
    display: block;
    font-size: 0.9rem;
    color: var(--c-muted);
    margin-top: 4px;
  }

  #snooze-linktree .lt-card-arrow {
    font-size: 1.1rem;
    color: var(--c-coral);
    flex-shrink: 0;
  }

  #snooze-linktree .lt-age {
    display: grid;
    gap: 10px;
    padding: 2px 2px 4px;
  }

  #snooze-linktree .lt-section-title {
    margin: 0;
    font-weight: 600;
    color: var(--c-navy);
    font-size: 0.92rem;
    text-align: center;
  }

  #snooze-linktree .lt-tiles {
    display: grid;
    grid-template-columns: repeat(4, minmax(0, 1fr));
    gap: 8px;
  }

  #snooze-linktree .lt-tile {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    padding: 10px 6px;
    border-radius: 999px;
    background: rgba(255, 255, 255, 0.95);
    font-weight: 600;
    color: var(--c-navy);
    box-shadow: var(--shadow-soft);
    animation: lt-fade-up 0.5s ease backwards;
    transition: transform 0.2s ease, box-shadow 0.2s ease;
    min-height: 44px;
  }

  #snooze-linktree .lt-tile:nth-of-type(1) { animation-delay: 0.05s; }
  #snooze-linktree .lt-tile:nth-of-type(2) { animation-delay: 0.09s; }
  #snooze-linktree .lt-tile:nth-of-type(3) { animation-delay: 0.13s; }
  #snooze-linktree .lt-tile:nth-of-type(4) { animation-delay: 0.17s; }

#snooze-linktree .lt-tile:hover {
  transform: translateY(-1px);
  box-shadow: 0 10px 20px rgba(31, 41, 59, 0.12);
}

#snooze-linktree .lt-footer {
  margin-top: 32px;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 16px;
}

#snooze-linktree .lt-site-link {
  font-size: 0.9rem;
  font-weight: 600;
  color: var(--c-coral);
  padding: 6px 4px;
  transition: color 0.2s ease;
}

#snooze-linktree .lt-site-link:hover {
  color: var(--c-coral-hover);
}

#snooze-linktree .lt-socials {
  display: inline-flex;
  gap: 14px;
  padding: 10px 16px;
  border-radius: 999px;
  background: rgba(255, 255, 255, 0.9);
  box-shadow: var(--shadow-soft);
}

#snooze-linktree .lt-social {
  width: 44px;
  height: 44px;
  border-radius: 50%;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  color: var(--c-navy);
  transition: transform 0.2s ease, box-shadow 0.2s ease;
}

#snooze-linktree .lt-social svg {
  width: 18px;
  height: 18px;
  fill: currentColor;
}

#snooze-linktree .lt-social:hover {
  transform: translateY(-1px);
  box-shadow: 0 8px 16px rgba(31, 41, 59, 0.12);
}

  @media (max-width: 520px) {
    #snooze-linktree .lt-shell {
      padding: 32px 18px 48px;
    }

    #snooze-linktree .lt-hero {
      padding: 28px 20px;
    }

    #snooze-linktree .lt-card {
      padding: 14px 16px;
    }
  }

  @media (min-width: 768px) {
    #snooze-linktree .lt-shell {
      padding: 56px 24px 72px;
    }
  }

  @media (prefers-reduced-motion: reduce) {
    #snooze-linktree .lt-card,
    #snooze-linktree .lt-tile {
      animation: none;
      opacity: 1;
      transform: none;
      transition: none;
    }

    #snooze-linktree .lt-primary,
    #snooze-linktree .lt-primary:hover {
      transition: none;
    }
  }

settings.js:
document.addEventListener('DOMContentLoaded', function () {
  const wrapper = document.getElementById('snooze-linktree');
  if (!wrapper) return;

  // Card/tile entrance is pure CSS (see lt-fade-up in the stylesheet) so
  // content is never gated on JS running or on scroll position. This
  // script only handles the primary button's press feedback.
  const primary = wrapper.querySelector('[data-primary-link]');

  if (primary) {
    primary.addEventListener('click', () => {
      primary.classList.add('is-pressed');
      setTimeout(() => primary.classList.remove('is-pressed'), 220);
    });
  }
});
